def solve(grid):
    h, w = len(grid), len(grid[0])
    result = []
    for ri in range(h//3):
        row_result = []
        for ci in range(w//3):
            subgrid = [grid[ri*3 + i][ci*3:(ci+1)*3] for i in range(3)]
            counts = {}
            for r in subgrid:
                for v in r:
                    if v != 5:
                        counts[v] = counts.get(v, 0) + 1
            if counts:
                max_color = max(counts.items(), key=lambda x: x[1])[0]
            else:
                max_color = 5
            row_result.append(max_color)
        result.append(row_result)
    return result

